import React, { useMemo, useState } from "react";

function formatDate(date) {
  return date.toLocaleString("en-US", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

export default function GatepassHtmlPage() {
  const [historyData, setHistoryData] = useState([]);

  const [applyDate, setApplyDate] = useState("");
  const [leaveType, setLeaveType] = useState("");
  const [leaveFrom, setLeaveFrom] = useState("");
  const [outTime, setOutTime] = useState("");
  const [leaveTo, setLeaveTo] = useState("");
  const [inTime, setInTime] = useState("");
  const [reason, setReason] = useState("Select Reason");
  const [hostelName, setHostelName] = useState("Select Hostel Name");
  const [approvedBy, setApprovedBy] = useState("");

  const leaveTypeLabel = useMemo(() => {
    if (leaveType === "dayOut") return "Day Out";
    if (leaveType === "nightOut") return "Night Out";
    return "";
  }, [leaveType]);

  function onSubmit(e) {
    e.preventDefault();

    const leaveFromDate = new Date(leaveFrom);
    const leaveToDate = new Date(leaveTo);

    if (!leaveType || !leaveFrom || !leaveTo || !reason || !approvedBy) {
      alert("Please fill out all fields.");
      return;
    }

    const newEntry = {
      leaveType: leaveTypeLabel,
      leaveFromTo: `${formatDate(leaveFromDate)} to ${formatDate(leaveToDate)}`,
      reason: reason,
      approvedBy: approvedBy,
    };

    setHistoryData((prev) => [...prev, newEntry]);

    // reset like original
    setApplyDate("");
    setLeaveType("");
    setLeaveFrom("");
    setOutTime("");
    setLeaveTo("");
    setInTime("");
    setReason("Select Reason");
    setHostelName("Select Hostel Name");
    setApprovedBy("");
  }

  return (
    <>
      <style>{`
        body {
          font-family: Arial, Helvetica, sans-serif;
          margin: 0;
          padding: 20px;
          background-color: #f0f0f0;
        }

        .profile-card .col-11{
          line-height: 0.7;
          flex: 1;
        }

        .container {
          background-color: white;
          border-radius: 5px;
          padding: 20px;
          max-width: 1150px;
          margin: 0 auto;
        }

        .profile-card {
          background-color: #f8f8f8;
          border-left: 4px solid #ff6b6b;
          padding: 15px;
          margin-bottom: 20px;
        }

        .profile-card .col-1{
          flex: 0 0 auto;
          width: auto;
          padding-right: 15px;
        }

        .profile-card .row{
          display: flex;
          align-items: center;
        }

        .profile-card h4 {
          margin-bottom: 5px;
        }

        .profile-card .p{
          margin: 0 0 5px;
        }

        .gatepass-form {
          background-color: #ffffff;
          padding: 20px;
          border-left: 4px solid rgb(119, 201, 221) ;
          margin-bottom: 20px;
        }

        .gatepass-form h5 {
          margin-bottom: 15px;
          color: rgb(159, 37, 37);
        }

        .btn-submit {
          background-color: red;
          color: white;
          border: none;
          padding: 10px 20px;
          border-radius: 5px;
          width: 10%;
          max-width: 200px;
        }

        .view-btn {
          background-color: red;
          color: white;
          padding: 5px 10px;
          border-radius: 4px;
          float: right;
          border: none;
        }

        .profile-card img{
          border-radius: 50%;
          margin-bottom: 0;
          width: 70px;
          height: 70px;
        }

        .student {
          margin-left:1px;
        }

        @media (max-width: 1200px) {
          .container {
            max-width: 95%;
          }
        }

        @media (max-width: 768px) {
          body {
            padding: 10px;
          }

          .container {
            padding: 15px;
          }

          .profile-card, .gatepass-form {
            margin: 0 0 15px 0;
          }

          .gatepass-form {
            padding: 15px;
          }

          .btn-submit {
            width: 100%;
          }

          .row {
            flex-direction: column;
          }

          .col {
            margin-bottom: 15px;
          }

          .history-section table{
            font-size: 0.9em;
          }
        }

        @media (max-width: 576px) {
          .profile-card .row {
            flex-direction: row;
          }

          .profile-card .col-1,
          .profile-card .col-11 {
            width: auto;
          }

          .profile-card img {
            max-width: 50px;
            height: auto;
          }

          .profile-card .col-11 {
            font-size: 0.9em;
          }

          .gatepass-form input[type="date"],
          .gatepass-form input[type="time"],
          .gatepass-form select,
          .gatepass-form input[type="text"] {
            width: 100%;
          }

          .history-section table{
            font-size: 0.8em;
          }
        }

        table {
          width: 100%;
          border-collapse: collapse;
        }
        th, td {
          padding: 8px;
          text-align: center;
          font-family: Arial, Helvetica, sans-serif;
          background-color: rgb(245, 242, 242);
        }
        th {
          background-color: rgb(151, 151, 151);
        }

        .history-section{
          width: 100%;
          height: auto;
          background-color:white;
          margin: 50px auto ;
          padding: 20px;
        }

        .history-section h5{
          color: rgb(163, 32, 32);
        }
      `}</style>

      <div className="container mt-4">
        <div className="profile-card">
          <div className="row d-flex align-items-center justify-content-between">
            <div className="col-1 d-flex align-items-center ">
              <img src="star programer.png" width="70" height="70" className="student" alt="" />
            </div>

            <div className="col-11">
              <h4>Hi, User</h4>
              <p>User's Parent Name</p>
              <p>Roll number</p>
              <p>2023-CUP-BE-CSE</p>
            </div>
          </div>
        </div>

        <div className="gatepass-form">
          <h5>
            <b>Gatepass Request</b>
          </h5>
          <form id="gatepassForm" onSubmit={onSubmit}>
            <div className="mb-3">
              <label htmlFor="applyDate">
                <b>Apply Date</b>
              </label>
              &nbsp;&nbsp;&nbsp;&nbsp;

              <input type="date" id="applyDate" value={applyDate} onChange={(e) => setApplyDate(e.target.value)} />
            </div>

            <div className="mb-3">
              <label htmlFor="apply">
                <b>Appy For</b>
              </label>
              &nbsp;&nbsp;&nbsp;&nbsp;

              <input
                type="radio"
                name="leaveType"
                id="dayOut"
                checked={leaveType === "dayOut"}
                onChange={() => setLeaveType("dayOut")}
              />
              <label htmlFor="apply">Day Out</label>
              &nbsp;&nbsp;&nbsp;&nbsp;

              <input
                type="radio"
                name="leaveType"
                id="nightOut"
                checked={leaveType === "nightOut"}
                onChange={() => setLeaveType("nightOut")}
              />
              <label htmlFor="apply">Night Out</label>
            </div>

            <div className="row mb-3">
              <div className="col">
                <label htmlFor="outDate">
                  <b>Out Date</b>
                </label>
                <br />
                <input type="date" id="leaveFrom" value={leaveFrom} onChange={(e) => setLeaveFrom(e.target.value)} />
              </div>

              <div className="col">
                <label htmlFor="outTime">
                  <b>Out Time(approx i.e.4:50 PM)</b>
                </label>
                <br />
                <input
                  type="time"
                  id="outTime"
                  placeholder="Time(approximate)"
                  value={outTime}
                  onChange={(e) => setOutTime(e.target.value)}
                />
              </div>

              <div className="col">
                <label htmlFor="inDate">
                  <b>In Date</b>
                </label>
                <br />
                <input type="date" id="leaveTo" value={leaveTo} onChange={(e) => setLeaveTo(e.target.value)} />
              </div>

              <div className="col">
                <label htmlFor="inTime">
                  <b>In Time(approx i.e.7:00 PM)</b>
                </label>
                <br />
                <input
                  type="time"
                  id="inTime"
                  placeholder="Time(approximate)"
                  value={inTime}
                  onChange={(e) => setInTime(e.target.value)}
                />
              </div>
            </div>

            <div className="mb-3">
              <label htmlFor="leaveReason" id="reason">
                <b>Leave Required Reason</b>
              </label>
              <select className="form-select" id="leaveReason" value={reason} onChange={(e) => setReason(e.target.value)}>
                <option>Select Reason</option>
                <option value="Medical">Medical</option>
                <option value="Personal">Personal</option>
                <option value="Family">Family</option>
                <option value="Emergency">Emergency</option>
              </select>
            </div>

            <div className="mb-3">
              <label htmlFor="hostelName">
                <b>Hostel Name</b>
              </label>
              <select className="form-select" id="hostelName" value={hostelName} onChange={(e) => setHostelName(e.target.value)}>
                <option>Select Hostel Name</option>
                <option value="Nightingle A">Nightingle A</option>
                <option value="Pie A">Pie A</option>
                <option value="Pie B">Pie B</option>
                <option value="Pie C">Pie C</option>
                <option value="Vasco">Vasco</option>
                <option value="Columbus">Columbus</option>
                <option value="Marco pol">Marco polo</option>
                <option value="Magellan">Magellan</option>
                <option value="Armstrong">Armstrong</option>
                <option value="Darwin B">Darwin B</option>
                <option value="IBN Battuta A">IBN Batutta A</option>
                <option value="IBN Battuta B">IBN Batutta B</option>
                <option value="Aristotle">Aristotle</option>
                <option value="Archimedes"> Archimedes</option>
                <option value="Franklin">Franklin</option>
                <option value="IBN Battuta C">IBN Battuta C</option>
                <option value="Nightingle B">Nightingle B</option>
              </select>
            </div>

            <label htmlFor="fname">
              <b>Approved By</b>
            </label>
            <br />
            <input
              type="text"
              id="approvedBy"
              name="approvedBy"
              placeholder="Warden Name"
              value={approvedBy}
              onChange={(e) => setApprovedBy(e.target.value)}
            />
            <br />
            <br />
            <button type="submit" className="btn-submit">
              Submit
            </button>
          </form>
        </div>
      </div>

      <div className="history-section">
        <h5>
          <b>Gatepass History</b>
        </h5>
        <div id="historyList"></div>

        <table>
          <thead>
            <tr>
              <th>#</th>
              <th>Leave Type</th>
              <th>Leave From To</th>
              <th>Reason</th>
              <th>Approved By</th>
            </tr>
          </thead>
          <tbody id="table-data">
            {historyData.map((item, index) => (
              <tr key={index}>
                <td>{index + 1}</td>
                <td>{item.leaveType}</td>
                <td>{item.leaveFromTo}</td>
                <td>{item.reason}</td>
                <td>{item.approvedBy}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
}
